def features(x, degree, cross=True):
    from itertools import combinations_with_replacement
    inds = [i for d in range(1, degree + 1) for i in combinations_with_replacement(range(x.shape[1]), d) if cross or len(set(i)) == 1]
    return (np.column_stack([np.ones(len(x))] + [np.prod(x[:, i], axis=1) for i in inds]), ['1'] + [''.join((str(j) for j in i)) for i in inds])

def robust(a, b):
    w = np.ones(len(a))
    for _ in range(150):
        c = np.linalg.lstsq(a * w[:, None], b * w[:, None], rcond=None)[0]
        r = np.linalg.norm(b - a @ c, axis=1)
        w = np.sqrt(np.minimum(1, max(1e-10, 0.08 * np.median(r)) / np.maximum(r, 1e-15)))
    good = np.argsort(r)[:len(r) - 3]
    c = np.linalg.lstsq(a[good], b[good], rcond=None)[0]
    return (c, np.linalg.norm(b - a @ c, axis=1), good)

def _scalar_design(z):
    interaction = z[:, 0] * z[:, 2] + z[:, 1] * z[:, 3]
    return np.column_stack((z, interaction))

def _trajectory(x, target, x_test, t):
    from scipy.optimize import least_squares

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def residual(rates):
        b = basis(rates)
        return (b @ _fit(b, target.T) - target.T).ravel()
    rates = least_squares(residual, [0.4, 1.8], bounds=([0.01, 0.8], [0.8, 8.0])).x
    b = basis(rates)
    return x_test @ _fit(x, _fit(b, target.T).T) @ b.T
